interface Image {
  display(): void;
}

class RealImage implements Image {
  constructor(private url: string) { this.loadFromDisk(); }
  private loadFromDisk() { /* fetch full-resolution image */ }
  display() { /* render already-loaded image */ }
}

class ImageProxy implements Image {
  private real: RealImage | null = null;
  constructor(private url: string) {}

  display() {
    if (!this.real) {
      this.real = new RealImage(this.url); // only loads on first real use
    }
    this.real.display();
  }
}

// Nothing loads until display() is actually called
const avatars = urls.map((url) => new ImageProxy(url));
